create table permissions (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), name varchar(100) not null, primary key (id)) engine=InnoDB;
create table product_categories (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), category_name varchar(255) not null, primary key (id)) engine=InnoDB;
create table products (cost_price decimal(10,2) not null, is_active bit not null, reorder_level integer not null, selling_price decimal(10,2) not null, category_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), barcode varchar(255) not null, product_name varchar(255) not null, sku varchar(255) not null, primary key (id)) engine=InnoDB;
